async function main() {
  const target = 1900;
  const start = await prisma.investigationMaster.count();
  let added = 0;
  let skipped = 0;
  for (const item of candidates) {
    const current = await prisma.investigationMaster.count();
    if (current >= target) break;
    const byCode = await prisma.investigationMaster.findUnique({ where: { code: item.code }, select: { id: true } });
    if (byCode) { skipped++; continue; }
    const byName = await prisma.investigationMaster.findFirst({ where: { name: item.name }, select: { id: true } });
    if (byName) { skipped++; continue; }
    await prisma.investigationMaster.create({ data: {
      code: item.code, name: item.name, shortName: item.name, category: item.category,
      department: item.category, specimen: "As applicable",
      corporateBenchmarkRate: item.corporateBenchmarkRate, rate: item.rate, active: true,
    }});
    added++;
  }
  const end = await prisma.investigationMaster.count();
  console.log(`Investigation secondary expansion: started ${start}, added ${added}, skipped ${skipped}, final ${end}.`);
  console.log("Pricing rule for non-SMS entries: SAMS = corporate/market benchmark × 0.65; final rate is never zero.");
}

main().catch((error) => { console.error(error); process.exit(1); }).finally(async () => prisma.$disconnect());
